pub struct tbpLibrationPointBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> tbpLibrationPointBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_POINT(&mut self, POINT: rfmLibrationPoint) {
        self.fbb_.push_slot::<rfmLibrationPoint>(tbpLibrationPoint::VT_POINT, POINT, rfmLibrationPoint::UNSPECIFIED);
    }

    #[inline]
    pub fn add_X(&mut self, X: f64) {
        self.fbb_.push_slot::<f64>(tbpLibrationPoint::VT_X, X, 0.0);
    }

    #[inline]
    pub fn add_Y(&mut self, Y: f64) {
        self.fbb_.push_slot::<f64>(tbpLibrationPoint::VT_Y, Y, 0.0);
    }

    #[inline]
    pub fn add_Z(&mut self, Z: f64) {
        self.fbb_.push_slot::<f64>(tbpLibrationPoint::VT_Z, Z, 0.0);
    }

    #[inline]
    pub fn add_JACOBI(&mut self, JACOBI: f64) {
        self.fbb_.push_slot::<f64>(tbpLibrationPoint::VT_JACOBI, JACOBI, 0.0);
    }

    #[inline]
    pub fn add_EIGENVALUES_REAL(&mut self, EIGENVALUES_REAL: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , f64>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(tbpLibrationPoint::VT_EIGENVALUES_REAL, EIGENVALUES_REAL);
    }

    #[inline]
    pub fn add_EIGENVALUES_IMAGINARY(&mut self, EIGENVALUES_IMAGINARY: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , f64>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(tbpLibrationPoint::VT_EIGENVALUES_IMAGINARY, EIGENVALUES_IMAGINARY);
    }

    #[inline]
    pub fn add_STABLE(&mut self, STABLE: bool) {
        self.fbb_.push_slot::<bool>(tbpLibrationPoint::VT_STABLE, STABLE, false);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> tbpLibrationPointBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        tbpLibrationPointBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<tbpLibrationPoint<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

