        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<tbpPeriodicOrbit>>("ORBIT", Self::VT_ORBIT, false)?
            .visit_field::<tbpStationKeepingStrategy>("STRATEGY", Self::VT_STRATEGY, false)?
