impl TBPT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<TBP<'b>> {
        let ID = self.ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let CREATED_AT_MS = self.CREATED_AT_MS;
        let PRODUCER = self.PRODUCER.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let PROBLEM = self.PROBLEM;
        let SYSTEM = self.SYSTEM.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let STATUS = self.STATUS;
        let ERROR_CODE = self.ERROR_CODE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let ERROR_MESSAGE = self.ERROR_MESSAGE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let PROPAGATION = self.PROPAGATION.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let TRAJECTORY = self.TRAJECTORY.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let LIBRATION_POINTS = self.LIBRATION_POINTS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let STATE = self.STATE.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let JACOBI = self.JACOBI;
        let ORBITS = self.ORBITS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let TRANSFER = self.TRANSFER.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let STATION_KEEPING = self.STATION_KEEPING.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let FRAME_CONVERSION = self.FRAME_CONVERSION.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let CONTINUATION = self.CONTINUATION.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let MANIFOLDS = self.MANIFOLDS.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let CONSTELLATION = self.CONSTELLATION.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let SURFACE_ANALYSIS = self.SURFACE_ANALYSIS.as_ref().map(|x|{
            x.pack(_fbb)
        });
        TBP::create(_fbb, &TBPArgs{
            ID,
            CREATED_AT_MS,
            PRODUCER,
            PROBLEM,
            SYSTEM,
            STATUS,
            ERROR_CODE,
            ERROR_MESSAGE,
            PROPAGATION,
            TRAJECTORY,
            LIBRATION_POINTS,
            STATE,
            JACOBI,
            ORBITS,
            TRANSFER,
            STATION_KEEPING,
            FRAME_CONVERSION,
            CONTINUATION,
            MANIFOLDS,
            CONSTELLATION,
            SURFACE_ANALYSIS,
        })
    }
}

/// Verifies that a buffer of bytes contains a `TBP`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_tbp_unchecked`.
#[inline]
pub fn root_as_tbp(buf: &[u8]) -> Result<TBP<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<TBP>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `TBP` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_tbp_unchecked`.
#[inline]
pub fn size_prefixed_root_as_tbp(buf: &[u8]) -> Result<TBP<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<TBP>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `TBP` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_tbp_unchecked`.
#[inline]
pub fn root_as_tbp_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<TBP<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<TBP<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `TBP` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_tbp_unchecked`.
#[inline]
pub fn size_prefixed_root_as_tbp_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<TBP<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<TBP<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a TBP and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `TBP`.
#[inline]
pub unsafe fn root_as_tbp_unchecked(buf: &[u8]) -> TBP<'_> {
    unsafe { ::flatbuffers::root_unchecked::<TBP>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed TBP and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `TBP`.
#[inline]
pub unsafe fn size_prefixed_root_as_tbp_unchecked(buf: &[u8]) -> TBP<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<TBP>(buf) }
}

pub const TBP_IDENTIFIER: &str = "$TBP";

#[inline]
pub fn tbp_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, TBP_IDENTIFIER, false)
}

#[inline]
pub fn tbp_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, TBP_IDENTIFIER, true)
}

#[inline]
pub fn finish_tbp_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<TBP<'a>>
) {
    fbb.finish(root, Some(TBP_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_tbp_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<TBP<'a>>
) {
    fbb.finish_size_prefixed(root, Some(TBP_IDENTIFIER));
}
